mapper.select:
SELECT * FROM chat_session
WHERE agent_id=#{agentId,typeHandler=com.febridge.persistence.UuidTypeHandler}
AND owner_user_id=#{ownerId,typeHandler=com.febridge.persistence.UuidTypeHandler}
ORDER BY updated_at DESC, id LIMIT 100

SELECT * FROM (
    SELECT * FROM chat_turn
    WHERE session_id=#{id,typeHandler=com.febridge.persistence.UuidTypeHandler}
    ORDER BY sequence DESC LIMIT 100
) recent ORDER BY sequence
